SELECT json_extract(value, '$.candidateId') AS candidateId, json_extract(value, '$.name') AS name, json_extract(value, '$.old') AS old, json_extract(value, '$.engine.value') AS next, json_extract(value, '$.engine.routes') AS routes, json_extract(value, '$.engine.unresolvedIngredients') AS gaps, json_extract(value, '$.windowSensitive') AS windowSensitive, json_extract(value, '$.formulaFingerprint') AS formulaFingerprint FROM json_each(readfile('data/research/shampoo-inci/approved-weight-consistency-v1/audit.json'), '$.rows');
